// src/qrcode/qrApi.ts
// qr-worker（Cloudflare Workers + D1）とやり取りするAPIクライアント。

export interface QrRecord {
  id: number;
  画像ファイル名: string;
  QRコード画像?: string;
  QRファイル名: string;
  カウント: string;
  分類: string;
  旧ファイル名: string;
  更新日: string;
  読み取りデータ: string;
}

export type NewQrRecord = Pick<
  QrRecord,
  '画像ファイル名' | 'QRファイル名' | 'カウント' | '分類' | '旧ファイル名' | '読み取りデータ'
>;

// boatrace/lib/api.js の PROXY_BASE と同じ流儀。.env の REACT_APP_QR_API_BASE で
// デプロイ済みWorkerを指す。未設定時はローカルの `wrangler dev`（既定 8787番）を想定。
const API_BASE = process.env.REACT_APP_QR_API_BASE || 'http://localhost:8787';

const ADMIN_KEY_STORAGE_KEY = 'qr_admin_key';

export function getAdminKey(): string {
  return localStorage.getItem(ADMIN_KEY_STORAGE_KEY) || '';
}

export function setAdminKey(key: string): void {
  localStorage.setItem(ADMIN_KEY_STORAGE_KEY, key);
}

export function clearAdminKey(): void {
  localStorage.removeItem(ADMIN_KEY_STORAGE_KEY);
}

/** 指定した管理キーがWorker側の設定と一致するか確認する（キーはlocalStorageに保存しない）。 */
export async function verifyAdminKey(key: string): Promise<boolean> {
  const res = await fetch(`${API_BASE}/api/admin/verify`, {
    headers: { 'X-Admin-Key': key },
  });
  return res.ok;
}

async function parseJsonOrThrow(response: Response): Promise<any> {
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    throw new Error(data.error || `HTTP ${response.status}`);
  }
  return data;
}

export async function fetchQrRecords(): Promise<QrRecord[]> {
  const res = await fetch(`${API_BASE}/api/qr`);
  return parseJsonOrThrow(res);
}

export async function createQrRecord(data: NewQrRecord): Promise<QrRecord> {
  const res = await fetch(`${API_BASE}/api/qr`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Admin-Key': getAdminKey(),
    },
    body: JSON.stringify(data),
  });
  return parseJsonOrThrow(res);
}

export async function deleteQrRecord(id: number): Promise<void> {
  const res = await fetch(`${API_BASE}/api/qr/${id}`, {
    method: 'DELETE',
    headers: {
      'X-Admin-Key': getAdminKey(),
    },
  });
  await parseJsonOrThrow(res);
}
