import React, { useEffect, useRef, useState } from 'react';
import { Container, Table, Badge, Spinner, Alert, Card, Form, Button, Row, Col } from 'react-bootstrap';
import jsQR from 'jsqr';
import {
  QrRecord,
  fetchQrRecords,
  createQrRecord,
  deleteQrRecord,
  getAdminKey,
  setAdminKey,
  clearAdminKey,
  verifyAdminKey,
} from './qrApi';

const QrUpdate: React.FC = () => {
  // ==========================================
  // 0. 管理キーによるゲート
  // ==========================================
  const [checkingGate, setCheckingGate] = useState(true);
  const [unlocked, setUnlocked] = useState(false);
  const [keyInput, setKeyInput] = useState('');
  const [gateError, setGateError] = useState<string | null>(null);
  const [gateSubmitting, setGateSubmitting] = useState(false);

  useEffect(() => {
    const stored = getAdminKey();
    if (!stored) {
      setCheckingGate(false);
      return;
    }
    verifyAdminKey(stored)
      .then((ok) => {
        if (ok) setUnlocked(true);
        else clearAdminKey();
      })
      .finally(() => setCheckingGate(false));
  }, []);

  const handleGateSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setGateSubmitting(true);
    setGateError(null);
    try {
      const ok = await verifyAdminKey(keyInput);
      if (ok) {
        setAdminKey(keyInput);
        setUnlocked(true);
      } else {
        setGateError('管理キーが違います');
      }
    } catch (err: any) {
      setGateError(err.message || '確認に失敗しました');
    } finally {
      setGateSubmitting(false);
    }
  };

  const handleLock = () => {
    clearAdminKey();
    setUnlocked(false);
    setKeyInput('');
  };

  const [records, setRecords] = useState<QrRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  const [category, setCategory] = useState('');
  const [qrFileName, setQrFileName] = useState('');
  const [count, setCount] = useState('');
  const [imageFileName, setImageFileName] = useState('');
  const [readData, setReadData] = useState('');
  const [decodeError, setDecodeError] = useState<string | null>(null);
  const [decoding, setDecoding] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const loadRecords = () => {
    setLoading(true);
    fetchQrRecords()
      .then(setRecords)
      .catch((e) => setLoadError(e.message || 'データの取得に失敗しました'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    if (unlocked) loadRecords();
  }, [unlocked]);

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setDecodeError(null);
    setDecoding(true);

    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.width;
        canvas.height = img.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          setDecoding(false);
          setDecodeError('画像の解析に失敗しました');
          return;
        }
        ctx.drawImage(img, 0, 0);
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const code = jsQR(imageData.data, imageData.width, imageData.height);
        setDecoding(false);
        if (code) {
          setReadData(code.data);
          if (!imageFileName) setImageFileName(file.name);
        } else {
          setDecodeError('QRコードを検出できませんでした。画像を確認してください。');
        }
      };
      img.onerror = () => {
        setDecoding(false);
        setDecodeError('画像の読み込みに失敗しました');
      };
      img.src = reader.result as string;
    };
    reader.readAsDataURL(file);
  };

  const resetForm = () => {
    setCategory('');
    setQrFileName('');
    setCount('');
    setImageFileName('');
    setReadData('');
    setDecodeError(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!qrFileName.trim()) {
      setSubmitError('QRファイル名は必須です');
      return;
    }
    setSubmitting(true);
    setSubmitError(null);
    try {
      const created = await createQrRecord({
        画像ファイル名: imageFileName,
        QRファイル名: qrFileName.trim(),
        カウント: count,
        分類: category.trim(),
        旧ファイル名: '',
        読み取りデータ: readData,
      });
      setRecords((prev) => [created, ...prev]);
      resetForm();
    } catch (err: any) {
      setSubmitError(err.message || '追加に失敗しました');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (item: QrRecord) => {
    if (!window.confirm(`「${item.QRファイル名}」を削除しますか？`)) return;
    try {
      await deleteQrRecord(item.id);
      setRecords((prev) => prev.filter((r) => r.id !== item.id));
    } catch (err: any) {
      window.alert(err.message || '削除に失敗しました');
    }
  };

  if (checkingGate) {
    return <div className="text-center py-5"><Spinner animation="border" /></div>;
  }

  if (!unlocked) {
    return (
      <Container className="mt-5" style={{ maxWidth: '400px' }}>
        <Card className="shadow-sm">
          <Card.Body>
            <Card.Title className="text-center mb-3">🔒 QR管理画面</Card.Title>
            <Form onSubmit={handleGateSubmit}>
              <Form.Label className="small fw-bold text-muted mb-1">管理キー</Form.Label>
              <Form.Control
                type="password"
                autoFocus
                value={keyInput}
                onChange={(e) => setKeyInput(e.target.value)}
                placeholder="管理キーを入力"
              />
              {gateError && <div className="small text-danger mt-2">{gateError}</div>}
              <Button type="submit" variant="primary" className="w-100 mt-3" disabled={gateSubmitting || !keyInput}>
                {gateSubmitting ? '確認中...' : '開く'}
              </Button>
            </Form>
          </Card.Body>
        </Card>
      </Container>
    );
  }

  return (
    <Container className="mt-5 mb-5">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h2 className="mb-0">QR管理画面</h2>
        <Button size="sm" variant="outline-secondary" onClick={handleLock}>🔒 ロック</Button>
      </div>

      <Card className="shadow-sm mb-4">
        <Card.Header className="fw-bold">新規追加</Card.Header>
        <Card.Body>
          <Form onSubmit={handleSubmit}>
            <Row className="mb-3">
              <Col md={4}>
                <Form.Label className="small fw-bold text-muted mb-1">分類</Form.Label>
                <Form.Control value={category} onChange={(e) => setCategory(e.target.value)} placeholder="例: A-11" />
              </Col>
              <Col md={4}>
                <Form.Label className="small fw-bold text-muted mb-1">QRファイル名 *</Form.Label>
                <Form.Control value={qrFileName} onChange={(e) => setQrFileName(e.target.value)} placeholder="例: Xperia1_099" required />
              </Col>
              <Col md={4}>
                <Form.Label className="small fw-bold text-muted mb-1">カウント</Form.Label>
                <Form.Control value={count} onChange={(e) => setCount(e.target.value)} />
              </Col>
            </Row>

            <Row className="mb-3">
              <Col md={6}>
                <Form.Label className="small fw-bold text-muted mb-1">QRスクリーンショット画像</Form.Label>
                <Form.Control ref={fileInputRef} type="file" accept="image/*" onChange={handleImageChange} />
                {decoding && <div className="small text-muted mt-1"><Spinner animation="border" size="sm" className="me-1" />解析中...</div>}
                {decodeError && <div className="small text-danger mt-1">{decodeError}</div>}
              </Col>
              <Col md={6}>
                <Form.Label className="small fw-bold text-muted mb-1">読み取りデータ</Form.Label>
                <Form.Control
                  value={readData}
                  onChange={(e) => setReadData(e.target.value)}
                  placeholder="画像から自動入力、または手入力"
                />
              </Col>
            </Row>

            {submitError && <Alert variant="danger" className="py-2">{submitError}</Alert>}

            <Button type="submit" variant="primary" disabled={submitting}>
              {submitting ? '追加中...' : '追加'}
            </Button>
          </Form>
        </Card.Body>
      </Card>

      <h4 className="mb-3">登録済みデータ（{records.length}件）</h4>

      {loading ? (
        <div className="text-center py-5"><Spinner animation="border" /></div>
      ) : loadError ? (
        <Alert variant="danger">{loadError}</Alert>
      ) : (
        <Table striped bordered hover responsive className="shadow-sm">
          <thead className="table-dark">
            <tr>
              <th>画像ファイル名</th>
              <th>QRファイル名</th>
              <th>読み取りデータ</th>
              <th>分類</th>
              <th>カウント</th>
              <th>更新日</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {records.map((item) => (
              <tr key={item.id}>
                <td className="fw-bold">{item.画像ファイル名}</td>
                <td>{item.QRファイル名}</td>
                <td><code>{item.読み取りデータ}</code></td>
                <td><Badge bg="info">{item.分類}</Badge></td>
                <td className="text-center">{item.カウント}</td>
                <td>{item.更新日}</td>
                <td>
                  <Button size="sm" variant="outline-danger" onClick={() => handleDelete(item)}>削除</Button>
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}
    </Container>
  );
};

export default QrUpdate;
