import React from 'react';
import { Link } from 'react-router-dom';
import { Navbar as BootstrapNavbar, Container, Nav } from 'react-bootstrap';

const Navbar: React.FC = () => {
  return (
    // bg="dark" data-bs-theme="dark" でカッコいい黒背景になります
    <BootstrapNavbar bg="dark" data-bs-theme="dark" expand="lg" className="shadow-sm mb-4">
      <Container>
        {/* 左上のロゴ部分（クリックでHomeに戻る） */}
        <BootstrapNavbar.Brand as={Link} to="/">
          Page
        </BootstrapNavbar.Brand>
        
        {/* スマホ画面になった時のハンバーガーメニュー */}
        <BootstrapNavbar.Toggle aria-controls="basic-navbar-nav" />
        
        <BootstrapNavbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            {/* as={Link} をつけることで、画面遷移せずにサクサク動きます */}
            <Nav.Link as={Link} to="/table">血統</Nav.Link>
            <Nav.Link as={Link} to="/blood">配合</Nav.Link>
            <Nav.Link as={Link} to="/schedule">レープロ</Nav.Link>
            <Nav.Link as={Link} to="/stockcheck">株券</Nav.Link>
          </Nav>
        </BootstrapNavbar.Collapse>
      </Container>
    </BootstrapNavbar>
  );
};

export default Navbar;