/** フィルター用の全グレード一覧 */
export const ALL_KEITOU_GRADES: Exclude<KeitouGrade, null>[] = [
  "鉄板", "堅実", "平均", "一発", "爆発",
];

/**
 * TaneData 内の系統名を、指定した sex（1=種牡馬側 / 2=繁殖牝馬側）でフィルタし、
 * 重複を除いた一覧を返す。系統不明時の手動選択プルダウンの選択肢に使う。
 */
export function getAllKeitouNames(
  taneData: KeitouRecord[],
  sex?: 1 | 2
): string[] {
  const filtered =
    sex === undefined ? taneData : taneData.filter((k) => k.sex === sex);
  return Array.from(new Set(filtered.map((k) => k.horseKeitou)));
}
